      "name": "MvPolynomial.pderiv_C",
      "type": " {R : Type u} {σ : Type v} {a : R} [CommSemiring R] {i : σ} : (MvPolynomial.pderiv i) (MvPolynomial.C a) = 0",
      "module": "Mathlib.Algebra.MvPolynomial.PDeriv"
    },
    {
      "name": "MvPolynomial.pderiv_C_mul",
      "type": " {R : Type u} {σ : Type v} {a : R} [CommSemiring R] {f : MvPolynomial σ R} {i : σ} : (MvPolynomial.pderiv i) (MvPolynomial.C a * f) = MvPolynomial.C a * (MvPolynomial.pderiv i) f",
      "module": "Mathlib.Algebra.MvPolynomial.PDeriv"
    },
    {
      "name": "MvPolynomial.aeval_sumElim_pderiv_inl",
      "type": " {R : Type u} {σ : Type v} [CommSemiring R] {S : Type u_1} {τ : Type u_2} [CommRing S] [Algebra R S] (p : MvPolynomial (σ ⊕ τ) R) (f : τ → S) (j : σ) : (MvPolynomial.aeval (Sum.elim MvPolynomial.X (⇑MvPolynomial.C ∘ f))) ((MvPolynomial.pderiv (Sum.inl j)) p) = (MvPolynomial.pderiv j) ((MvPolynomial.aeval (Sum.elim MvPolynomial.X (⇑MvPolynomial.C ∘ f))) p)",
      "module": "Mathlib.Algebra.MvPolynomial.PDeriv"
    }
  ]
